CREATE PROCEDURE [dbo].[spRemove_AppCredential]
  @ClientId UNIQUEIDENTIFIER = NULL,
  @RecordBy UNIQUEIDENTIFIER = NULL,
  @StatusCode INT OUTPUT,
  @StatusMessage VARCHAR(1000) OUTPUT
AS

SET NOCOUNT ON;
BEGIN
  DECLARE @CurrentData DATETIME = GETUTCDATE();

  BEGIN TRANSACTION;
  BEGIN TRY
    UPDATE [Session]
    SET [ClosedAt] = @CurrentData,
        [IsActive] = 0
    WHERE [UserId] = @UserId;

    SET @StatusCode = 0;
    SET @StatusMessage = 'Session removed successfully';
    COMMIT TRANSACTION;
  END TRY
  BEGIN CATCH
    ROLLBACK TRANSACTION;
    SET @StatusCode = ERROR_NUMBER();
    SET @StatusMessage = ERROR_MESSAGE();
  END CATCH
END

CREATE PROCEDURE [dbo].[spRemove_Session]
  @UserId UNIQUEIDENTIFIER = NULL,
  @StatusCode INT OUTPUT,
  @StatusMessage VARCHAR(1000) OUTPUT
AS

SET NOCOUNT ON;
BEGIN
  DECLARE @CurrentData DATETIME = GETUTCDATE();

  IF @UserId IS NULL
  OR @RecordBy IS NULL
    SET @StatusCode = 1;
    SET @StatusMessage = 'Parameter is required';

  IF NOT EXISTS (SELECT [UserId] FROM [User] WHERE [UserId] = @UserId)
    SET @StatusCode = 2;
    SET @StatusMessage = 'User not found';

  BEGIN TRANSACTION;
  BEGIN TRY
    UPDATE [dbo].[User]
    SET
      [IsActive] = 0,
      [UpdatedBy] = @RecordBy,
      [UpdatedAt] = @CurrentData
    WHERE [UserId] = @UserId;

    COMMIT TRANSACTION;
    SET @StatusCode = 0;
    SET @StatusMessage = 'User removed successfully';
  END TRY
  BEGIN CATCH
    ROLLBACK TRANSACTION;
    SET @StatusCode = ERROR_NUMBER();
    SET @StatusMessage = ERROR_MESSAGE();
  END CATCH
END

CREATE PROCEDURE [dbo].[spRemove_User]
  @UserId UNIQUEIDENTIFIER = NULL,
  @RecordBy UNIQUEIDENTIFIER = NULL,
  @StatusCode INT OUTPUT,
  @StatusMessage VARCHAR(1000) OUTPUT
AS

SET NOCOUNT ON;
BEGIN
  DECLARE @CurrentDate DATETIME = GETUTCDATE();

  IF @ClientId IS NULL
  OR @AppName IS NULL
  OR @ClientSecret IS NULL
  OR @RecordBy IS NULL
  BEGIN
    SET @StatusCode = 1;
    SET @StatusMessage = 'Parameter is required';
    RETURN;
  END

  IF EXISTS (SELECT 1 FROM [dbo].[User] WHERE [Email] = @AppName)
  BEGIN
    SET @StatusCode = 2;
    SET @StatusMessage = 'Application name already exists';
    RETURN;
  END

  BEGIN TRY
    BEGIN TRANSACTION

    IF EXISTS (SELECT 1 FROM [dbo].[AppCredential] WHERE [ClientId] = @ClientId)
    BEGIN
      UPDATE [dbo].[AppCredential]
      SET
        [ClientSecret] = @ClientSecret,
        [UpdatedBy] = @RecordBy,
        [UpdatedAt] = @CurrentDate
      WHERE [ClientId] = @ClientId;

      SET @StatusCode = 0;
      SET @StatusMessage = 'Application updated successfully';
      COMMIT TRANSACTION;
      RETURN;
    END

    INSERT INTO [dbo].[AppCredential]
    (
      [ClientId],
      [ClientSecret],
      [IsActive],
      [CreatedBy],
      [CreatedAt],
      [UpdatedBy],
      [UpdatedAt]
    )
    VALUES
    (
      @ClientId,
      @ClientSecret,
      1,
      @RecordBy,
      @CurrentDate,
      @RecordBy,
      @CurrentDate
    );

    INSERT INTO [dbo].[User]
    (
      [UserId],
      [UserName],
      [Email],
      [Role],
      [CreatedBy],
      [CreatedAt],
      [UpdatedBy],
      [UpdatedAt]
    )
    VALUES
    (
      @ClientId,
      @AppName,
      @AppName,
      'app',
      @RecordBy,
      @CurrentDate,
      @RecordBy,
      @CurrentDate
    );

    SET @StatusCode = 0;
    SET @StatusMessage = 'Application saved successfully';
    COMMIT TRANSACTION;
  END TRY
  BEGIN CATCH
    SET @StatusCode = ERROR_NUMBER();
    SET @StatusMessage = ERROR_MESSAGE();
    ROLLBACK TRANSACTION;
  END CATCH
END

CREATE PROCEDURE [dbo].[spSave_AppCredebtial]
  @ClientId UNIQUEIDENTIFIER = NULL,
  @AppName VARCHAR(200) = NULL,
  @ClientSecret VARCHAR(64) = NULL,
  @RecordBy UNIQUEIDENTIFIER = NULL,
  @StatusCode INT OUTPUT,
  @StatusMessage VARCHAR(1000) OUTPUT
AS

SET NOCOUNT ON;
BEGIN
  DECLARE @CurrentData DATETIME = GETUTCDATE();

  IF @UserId IS NULL
  OR @SessionHash IS NULL
  BEGIN
    SET @StatusCode = 1;
    SET @StatusMessage = 'Parameter is require';
    RETURN;
  END

  BEGIN TRANSACTION
  BEGIN TRY
    IF EXISTS (SELECT 1 FROM [Session] WHERE [UserId] = @UserId AND [IsActive] = 1)
    BEGIN
      UPDATE [Session]
      SET [IsActive] = 0,
          [ClosedAt] = @CurrentData
      WHERE [UserId] = @UserId;
    END

    INSERT INTO [Session]
    VALUES (@SessionId, @UserId, @SessionHash, 1, @CurrentData, @CurrentData);

    COMMIT TRANSACTION;
    SET @StatusCode = 0;
    SET @StatusMessage = 'Session saved successfully'
  END TRY
  BEGIN CATCH
    ROLLBACK TRANSACTION;
    SET @StatusCode = ERROR_NUMBER();
    SET @StatusMessage = ERROR_MESSAGE()
  END CATCH
END

CREATE PROCEDURE [dbo].[spSave_Session]
  @SessionId UNIQUEIDENTIFIER = NULL,
  @UserId UNIQUEIDENTIFIER = NULL,
  @SessionHash VARCHAR(64) = NULL,
  @StatusCode INT OUT,
  @StatusMessage VARCHAR(1000) OUT
AS

SET NOCOUNT ON;
BEGIN
  DECLARE @CurrentData DATETIME = GETUTCDATE();

  IF @UserName IS NULL
  OR @Email IS NULL
  OR @Role IS NULL
  OR @RecordBy IS NULL
  BEGIN
    SET @StatusCode = 1;
    SET @StatusMessage = 'Parameter is required';
    RETURN;
  END

  IF @Role NOT IN ('admin', 'user')
  BEGIN
    SET @StatusCode = 2;
    SET @StatusMessage = 'Invalid role';
    RETURN;
  END

  IF EXISTS (SELECT 1 FROM [User] WHERE [UserId] = @UserId)
  BEGIN
    BEGIN TRANSACTION
    BEGIN TRY
      UPDATE [dbo].[User]
      SET
        [UserName] = @UserName,
        [Role] = @Role,
        [UpdatedBy] = @RecordBy,
        [UpdatedAt] = @CurrentData,
        [IsActive] = 1
      WHERE [UserId] = @UserId;

      COMMIT TRANSACTION;
      SET @StatusCode = 0;
      SET @StatusMessage = 'User saved successfully';
    END TRY
    BEGIN CATCH
      ROLLBACK TRANSACTION;
      SET @StatusCode = ERROR_NUMBER();
      SET @StatusMessage = ERROR_MESSAGE();
    END CATCH
  END
  ELSE
  BEGIN
    IF EXISTS (SELECT [UserId] FROM [User] WHERE [Email] = @Email)
    BEGIN
      SET @StatusCode = 3;
      SET @StatusMessage = 'User already exists';
      RETURN;
    END

    BEGIN TRANSACTION;
    BEGIN TRY
      INSERT INTO [dbo].[User]
      (
        [UserId],
        [UserName],
        [Email],
        [Role],
        [CreatedBy],
        [CreatedAt],
        [UpdatedBy],
        [UpdatedAt]
      )
      VALUES
      (
        @UserId,
        @UserName,
        @Email,
        @Role,
        @RecordBy,
        @CurrentData,
        @RecordBy,
        @CurrentData
      );

      COMMIT TRANSACTION;
      SET @StatusCode = 0;
      SET @StatusMessage = 'User saved successfully';
    END TRY
    BEGIN CATCH
      ROLLBACK TRANSACTION;
      SET @StatusCode = ERROR_NUMBER();
      SET @StatusMessage = ERROR_MESSAGE();
    END CATCH
  END
END

CREATE PROCEDURE [dbo].[spSave_User]
  @UserId UNIQUEIDENTIFIER = NULL,
  @UserName VARCHAR(500) = NULL,
  @Email VARCHAR(200) = NULL,
  @Role VARCHAR(100) = NULL,
  @RecordBy UNIQUEIDENTIFIER = NULL,
  @StatusCode INT OUTPUT,
  @StatusMessage VARCHAR(1000) OUTPUT
AS

BEGIN DECLARE @CurrentDate DATETIME = GETUTCDATE();
IF @ClientId IS NOT NULL BEGIN SELECT A.[ClientId], A.[ClientSecret], A.[CreatedAt], A.[UpdatedAt], A.[IsActive], A.[CreatedBy], B.[UserName] FROM [dbo].[AppCredential] A INNER JOIN [dbo].[User] B ON A.[ClientId] = B.[UserId] WHERE [ClientId] = @ClientId; RETURN; END
SET @TotalRecords = (SELECT COUNT(*) FROM [dbo].[AppCredential] A INNER JOIN [dbo].[User] B ON A.[ClientId] = B.[UserId]);
SELECT A.[ClientId], A.[ClientSecret], A.[CreatedAt], A.[UpdatedAt], A.[IsActive], A.[CreatedBy], B.[UserName] FROM [dbo].[AppCredential] A INNER JOIN [dbo].[User] B ON A.[ClientId] = B.[UserId] ORDER BY A.[CreatedAt] DESC OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY; END

CREATE PROCEDURE [dbo].[spSelect_AppCredential]
  @ClientId UNIQUEIDENTIFIER = NULL,
  @Search VARCHAR(200) = NULL,
  @PageNumber INT = 1,
  @PageSize INT = 10,
  @TotalRecords INT OUTPUT
AS

SET NOCOUNT ON; BEGIN IF @UserId IS NOT NULL BEGIN SET @TotalRecords = 1;
SELECT [UserId], [UserName], [Email], [Role], [IsActive], [CreatedBy], [CreatedAt], [UpdatedBy], [UpdatedAt] FROM [User] WHERE [UserId] = @UserId; RETURN; END
IF @Email IS NOT NULL BEGIN SET @TotalRecords = 1;
SELECT [UserId], [UserName], [Email], [Role], [IsActive], [CreatedBy], [CreatedAt], [UpdatedBy], [UpdatedAt] FROM [User] WHERE [Email] = @Email AND [IsActive] = 1; RETURN; END
IF @Search IS NOT NULL BEGIN SET @TotalRecords = ( SELECT COUNT(*) FROM [User] WHERE [UserName] LIKE '%' + @Search + '%' OR [Email] LIKE '%' + @Search + '%' OR [Role] LIKE '%' + @Search + '%' );
SELECT [UserId], [UserName], [Email], [Role], [IsActive], [CreatedBy], [CreatedAt], [UpdatedBy], [UpdatedAt] FROM [User] WHERE [UserName] LIKE '%' + @Search + '%' OR [Email] LIKE '%' + @Search + '%' OR [Role] LIKE '%' + @Search + '%' ORDER BY [CreatedAt] DESC OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY; RETURN; END
SET @TotalRecords = (SELECT COUNT(*) FROM [User]); SELECT [UserId], [UserName], [Email], [Role], [IsActive], [CreatedBy], [CreatedAt], [UpdatedBy], [UpdatedAt] FROM [User] ORDER BY [CreatedAt] DESC OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY; END

